import pytest

from bedrock_protocol import nbt, v2225

# generated by gophertunnel b8bd735:
# packet.StructureTemplateDataResponse{StructureName: "mystructure",
# Success: true, StructureTemplate: map[string]any{"format_version": int32(1)},
# ResponseType: packet.StructureTemplateResponseQuery}
QUERY = bytes.fromhex("0b6d79737472756374757265010a00030e666f726d61745f76657273696f6e020002")

# generated by gophertunnel b8bd735:
# packet.StructureTemplateDataResponse{StructureName: "mystructure",
# Success: false, ResponseType: packet.StructureTemplateResponseExport}
ABSENT_TAG = bytes.fromhex("0b6d797374727563747572650001")

# generated by gophertunnel b8bd735:
# packet.StructureTemplateDataResponse{StructureName: "",
# Success: true, ResponseType: 0}
EMPTY_TAG = bytes.fromhex("00010a000000")

GOLDENS = [
    pytest.param(
        v2225.StructureTemplateDataResponsePacket(
            structure_name="mystructure",
            structure_tag=nbt.CompoundTag({"format_version": nbt.IntTag(1)}),
            response_type=v2225.StructureTemplateResponseType.QUERY,
        ),
        QUERY,
        id="query",
    ),
    pytest.param(
        v2225.StructureTemplateDataResponsePacket(
            structure_name="mystructure",
            structure_tag=None,
            response_type=v2225.StructureTemplateResponseType.EXPORT,
        ),
        ABSENT_TAG,
        id="absent-tag",
    ),
    pytest.param(
        v2225.StructureTemplateDataResponsePacket(
            structure_name="",
            structure_tag=nbt.CompoundTag(),
            response_type=v2225.StructureTemplateResponseType.NONE,
        ),
        EMPTY_TAG,
        id="empty-tag",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_structure_template_data_response_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_structure_template_data_response_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
